"""``--cross-check``: a seeded 10 % sample regenerated by a second model of another family."""

import numpy as np
import pytest
from testsupport.qa_support import DATAGEN, SECOND, chunk, datagen_server, make_client, reply

from pruefstand.core.errors import ConfigError
from pruefstand.core.ids import ChunkId
from pruefstand.core.models.corpus import Chunk
from pruefstand.core.models.dataset import QACandidate
from pruefstand.dataset.cross_check import CrossCheckPlan, cross_check, pick_sample
from pruefstand.dataset.generate import GenStats

IDS = [f"gii-bgb-{n}#0" for n in (620, 621, 624, 625, 626)] + ["gii-bgb-622#1", "gii-kschg-1#1"]


def _cands(n: int) -> list[QACandidate]:
    return [
        QACandidate(
            question=f"Frage {i}?",
            answer="Antwort.",
            citation="§ 622 BGB",
            chunk_id=ChunkId(IDS[i % len(IDS)]),
            prompt_version="qa_factual_de_v1",
        )
        for i in range(n)
    ]


def test_ten_percent_of_thirty_is_three_and_seeded() -> None:
    a = pick_sample(30, 0.1, np.random.default_rng(7))
    b = pick_sample(30, 0.1, np.random.default_rng(7))
    assert a == b
    assert len(a) == 3
    assert a == sorted(set(a))
    assert pick_sample(30, 0.0, np.random.default_rng(7)) == []
    assert len(pick_sample(5, 0.1, np.random.default_rng(7))) == 1
    assert pick_sample(0, 0.1, np.random.default_rng(7)) == []


async def test_rows_hold_both_candidates_side_by_side() -> None:
    cands = _cands(10)
    chunks: dict[str, Chunk] = {c.chunk_id: c for c in map(chunk, IDS)}
    stats = GenStats()
    with datagen_server(reply(question="Zweite Frage?")) as (base, state):
        client, _ = make_client(base, model=SECOND)
        rows = await cross_check(
            cands,
            chunks,
            client,
            CrossCheckPlan(model=SECOND, primary_model=DATAGEN, fraction=0.3),
            np.random.default_rng(7),
            stats=stats,
        )
    assert len(rows) == 3
    assert state.posts() == 3
    assert all(r.second is not None and r.second.question == "Zweite Frage?" for r in rows)
    assert all(r.primary in cands for r in rows)
    assert (rows[0].primary_model, rows[0].second_model) == (DATAGEN, SECOND)
    assert stats.counts["cross_checked"] == 3


async def test_the_second_model_must_be_of_another_family() -> None:
    with datagen_server() as (base, state):
        client, _ = make_client(base)
        with pytest.raises(ConfigError, match="family"):
            await cross_check(
                _cands(3),
                {},
                client,
                CrossCheckPlan(model="github/openai/gpt-4o", primary_model=DATAGEN, fraction=0.5),
                np.random.default_rng(1),
            )
        with pytest.raises(ConfigError, match="gemma"):
            await cross_check(
                _cands(3),
                {},
                client,
                CrossCheckPlan(model="github/google/gemma-3", primary_model=DATAGEN, fraction=0.5),
                np.random.default_rng(1),
            )
    assert state.posts() == 0


async def test_a_failed_second_answer_is_kept_as_none() -> None:
    cands = _cands(2)
    chunks: dict[str, Chunk] = {c.chunk_id: c for c in map(chunk, IDS)}
    with datagen_server("kein json und auch kein repair") as (base, _state):
        client, _ = make_client(base, model=SECOND)
        rows = await cross_check(
            cands,
            chunks,
            client,
            CrossCheckPlan(model=SECOND, primary_model=DATAGEN, fraction=1.0),
            np.random.default_rng(1),
            stats=GenStats(),
        )
    assert [r.second for r in rows] == [None, None]
